-- Deep Dive into LLMs like ChatGPT (spec 013), the first course of the
-- Software developers role (content/course-llm-deep-dive.md). Based on
-- Andrej Karpathy's video https://www.youtube.com/watch?v=7xTGNNLPyMI.
-- Choices, steps, items and nodes are stored in a mixed order so they
-- don't give the answer away.

-- "AI apps on Azure" becomes the second course of the role.
update public.courses set position = 2 where id = 'software-developers';

insert into public.courses (id, role, title, position) values
  ('llm-deep-dive', 'software-developers', 'Deep Dive into LLMs like ChatGPT', 1);

insert into public.sections (id, course_id, position, title) values
  ('llm-pretraining', 'llm-deep-dive', 1, 'Pretraining: from the internet to a base model'),
  ('llm-post-training', 'llm-deep-dive', 2, 'Post-training: from base model to assistant'),
  ('llm-reinforcement-learning', 'llm-deep-dive', 3, 'Reinforcement learning and thinking models'),
  ('llm-using-llms', 'llm-deep-dive', 4, 'Using LLMs as a developer');

insert into public.lessons (id, section_id, position, title) values
  ('llm-collecting-the-internet', 'llm-pretraining', 1, 'Collecting the internet'),
  ('llm-tokenization', 'llm-pretraining', 2, 'Tokenization'),
  ('llm-inside-the-network', 'llm-pretraining', 3, 'Inside the neural network'),
  ('llm-inference', 'llm-pretraining', 4, 'Inference'),
  ('llm-training-gpt-2', 'llm-pretraining', 5, 'Training GPT-2'),
  ('llm-base-models', 'llm-pretraining', 6, 'Base models in action'),
  ('llm-conversations-as-data', 'llm-post-training', 1, 'Conversations as training data'),
  ('llm-hallucinations-and-tools', 'llm-post-training', 2, 'Hallucinations and tools'),
  ('llm-knowledge-vs-memory', 'llm-post-training', 3, 'Knowledge vs working memory'),
  ('llm-knowledge-of-self', 'llm-post-training', 4, 'Knowledge of self'),
  ('llm-tokens-to-think', 'llm-post-training', 5, 'Models need tokens to think'),
  ('llm-jagged-intelligence', 'llm-post-training', 6, 'Tokens and jagged intelligence'),
  ('llm-why-rl', 'llm-reinforcement-learning', 1, 'Why RL: the textbook analogy'),
  ('llm-how-rl-works', 'llm-reinforcement-learning', 2, 'How RL works'),
  ('llm-thinking-models', 'llm-reinforcement-learning', 3, 'Thinking models'),
  ('llm-alphago', 'llm-reinforcement-learning', 4, 'AlphaGo and going past human examples'),
  ('llm-rlhf', 'llm-reinforcement-learning', 5, 'RLHF'),
  ('llm-whats-coming', 'llm-using-llms', 1, 'What''s coming'),
  ('llm-choosing-models', 'llm-using-llms', 2, 'Tracking and choosing models'),
  ('llm-capstone', 'llm-using-llms', 3, 'Capstone: the whole picture');

insert into public.exercises (lesson_id, position, type, content, solution, explanation) values
  ('llm-collecting-the-internet', 1, 'multiple_choice',
   '{"question": "Where does most of the text for pretraining an LLM come from?", "options": ["Private chats from people using the app", "Only books scanned from libraries", "Text the model wrote about itself", "Public web pages, collected by crawlers and then cleaned"]}',
   '{"correct": 3}',
   'Pretraining starts from a huge crawl of the public web (for example Common Crawl). That raw crawl is then cleaned and filtered into a training dataset.'),
  ('llm-collecting-the-internet', 2, 'ordering',
   '{"question": "Put the steps of building a pretraining dataset in order.", "scenario": "You start with billions of raw web pages and want clean, useful text at the end.", "items": [{"id": "remove-duplicate-pages", "label": "Remove duplicate pages"}, {"id": "crawl-public-web-pages", "label": "Crawl public web pages"}, {"id": "remove-personal-information", "label": "Remove personal information"}, {"id": "block-unwanted-sites-by-their-url", "label": "Block unwanted sites by their URL"}, {"id": "keep-pages-in-the-languages-you-want", "label": "Keep pages in the languages you want"}, {"id": "pull-the-plain-text-out-of-the-html", "label": "Pull the plain text out of the HTML"}]}',
   '{"order": ["crawl-public-web-pages", "block-unwanted-sites-by-their-url", "pull-the-plain-text-out-of-the-html", "keep-pages-in-the-languages-you-want", "remove-duplicate-pages", "remove-personal-information"]}',
   'First you collect pages, then drop whole sites you never want (spam, malware, adult content). Next you strip the HTML down to text, keep the right languages, remove near-copies and finally scrub personal details such as addresses and phone numbers.'),
  ('llm-collecting-the-internet', 3, 'categorize',
   '{"question": "Which of these end up in the training data, and which are filtered out?", "buckets": [{"id": "keep-for-training", "label": "Keep for training"}, {"id": "filter-out", "label": "Filter out"}], "items": [{"id": "a-page-from-a-known-spam-site", "label": "A page from a known spam site"}, {"id": "a-step-by-step-cooking-guide", "label": "A step-by-step cooking guide"}, {"id": "someone-s-home-address-and-phone-number", "label": "Someone''s home address and phone number"}, {"id": "a-detailed-encyclopedia-article", "label": "A detailed encyclopedia article"}, {"id": "navigation-menus-and-html-markup", "label": "Navigation menus and HTML markup"}, {"id": "a-forum-thread-explaining-a-math-problem", "label": "A forum thread explaining a math problem"}]}',
   '{"items": {"a-detailed-encyclopedia-article": "keep-for-training", "a-page-from-a-known-spam-site": "filter-out", "navigation-menus-and-html-markup": "filter-out", "a-step-by-step-cooking-guide": "keep-for-training", "someone-s-home-address-and-phone-number": "filter-out", "a-forum-thread-explaining-a-math-problem": "keep-for-training"}}',
   'The goal is lots of varied, good-quality text. Spam, page markup and personal details add nothing useful and can do harm, so they are removed before training.'),
  ('llm-collecting-the-internet', 4, 'multiple_choice',
   '{"question": "Why do teams filter the web data so carefully?", "options": ["The model learns the patterns in its data, so junk in means junk out", "Filtering makes the model run faster after training", "The law requires every page to be read by a person", "Unfiltered text can''t be turned into tokens"]}',
   '{"correct": 0}',
   'An LLM picks up whatever patterns are in its training text. Clean, diverse, high-quality data leads to a better model, so the effort goes into the data first.'),
  ('llm-collecting-the-internet', 5, 'multiple_choice',
   '{"question": "Roughly how big is a large, filtered web dataset like FineWeb?", "options": ["There is no limit, it is the whole internet", "About 44 TB of text, around 15 trillion tokens", "About 44 MB, the size of a few books", "About 44 GB, the size of a movie collection"]}',
   '{"correct": 1}',
   'At the time of the video, FineWeb was about 44 TB, roughly 15 trillion tokens. It''s huge, but after filtering it''s far smaller than the whole web and fits on a few large hard drives.'),
  ('llm-collecting-the-internet', 6, 'multiple_choice',
   '{"question": "Your team wants to train a small model on your company''s support tickets. A colleague suggests using every ticket as-is, without cleaning. What''s the main risk?", "options": ["Training will be faster, but nothing else changes", "The model will refuse to answer support questions", "The model learns repeated boilerplate and may reproduce customers'' personal data", "The tickets can''t be split into tokens"]}',
   '{"correct": 2}',
   'The same cleaning steps apply to your own data: remove duplicates, signatures and noise, and scrub personal information. Otherwise the model learns the noise and can leak private details.'),
  ('llm-tokenization', 1, 'multiple_choice',
   '{"question": "Why is text turned into tokens before it goes into the network?", "options": ["Tokens hide the text from the people training the model", "Tokens remove the grammar so the model can learn faster", "The network works with a fixed set of symbols, so text must become a sequence of them", "Each token stores a full sentence"]}',
   '{"correct": 2}',
   'A neural network takes a sequence of symbols from a fixed vocabulary. Tokenization turns any text into such a sequence of token IDs, and back again.'),
  ('llm-tokenization', 2, 'ordering',
   '{"question": "Put these ways of representing text in order, from the longest sequence to the shortest.", "items": [{"id": "bytes-256-possible-symbols-8-times-short", "label": "Bytes: 256 possible symbols, 8 times shorter"}, {"id": "byte-pair-encoding-common-pairs-merged-i", "label": "Byte pair encoding: common pairs merged into new symbols"}, {"id": "tokens-about-100-000-symbols-a-much-shor", "label": "Tokens: about 100,000 symbols, a much shorter sequence"}, {"id": "bits-only-0-and-1-a-very-long-sequence", "label": "Bits: only 0 and 1, a very long sequence"}]}',
   '{"order": ["bits-only-0-and-1-a-very-long-sequence", "bytes-256-possible-symbols-8-times-short", "byte-pair-encoding-common-pairs-merged-i", "tokens-about-100-000-symbols-a-much-shor"]}',
   'Every step trades a longer sequence for more symbols. Grouping bits into bytes shortens the sequence 8 times, and byte pair encoding keeps merging common pairs until the vocabulary is around 100,000 tokens.'),
  ('llm-tokenization', 3, 'multiple_choice',
   '{"question": "Byte pair encoding keeps merging frequent pairs of symbols into new symbols. What does that give you?", "options": ["Perfect spelling for every word", "One token for every word in every language", "Longer sequences, in exchange for a smaller vocabulary", "Shorter sequences, in exchange for a bigger vocabulary"]}',
   '{"correct": 3}',
   'Each merge adds a symbol to the vocabulary and makes texts shorter. Shorter sequences matter because the network can only look at a limited number of tokens at once, and each token costs compute.'),
  ('llm-tokenization', 4, 'multiple_choice',
   '{"question": "About how many different tokens does the GPT-4 tokenizer have?", "options": ["About 100,000", "256", "Exactly one per English word", "About 10 million"]}',
   '{"correct": 0}',
   'The GPT-4 tokenizer has a vocabulary of about 100,000 tokens (100,277 at the time of the video). Many common words are a single token, while rare words are split into several.'),
  ('llm-tokenization', 5, 'categorize',
   '{"question": "You type \"hello world\" into a tokenizer viewer. Which changes give you a different token sequence?", "buckets": [{"id": "different-tokens", "label": "Different tokens"}, {"id": "same-tokens", "label": "Same tokens"}], "items": [{"id": "capitalizing-it-as-hello-world", "label": "Capitalizing it as \"Hello world\""}, {"id": "adding-an-extra-space-before-world", "label": "Adding an extra space before \"world\""}, {"id": "copying-the-same-text-into-another-app", "label": "Copying the same text into another app"}, {"id": "typing-exactly-hello-world-again", "label": "Typing exactly \"hello world\" again"}, {"id": "writing-hello-there-instead", "label": "Writing \"hello there\" instead"}]}',
   '{"items": {"capitalizing-it-as-hello-world": "different-tokens", "adding-an-extra-space-before-world": "different-tokens", "typing-exactly-hello-world-again": "same-tokens", "copying-the-same-text-into-another-app": "same-tokens", "writing-hello-there-instead": "different-tokens"}}',
   'Tokens depend on the exact characters, including case and spaces. The same text always gives the same tokens, but small edits can change them.'),
  ('llm-tokenization', 6, 'multiple_choice',
   '{"question": "Your app sends long prompts to an LLM API that charges per token. Which change lowers the bill without losing information?", "options": ["Write the prompt in ALL CAPS", "Split the same text into many smaller requests", "Remove the boilerplate text you repeat in every prompt", "Replace every space with an underscore"]}',
   '{"correct": 2}',
   'You pay for tokens, so sending fewer tokens costs less. Odd formatting usually creates more tokens, and splitting the same text into requests doesn''t reduce them.'),
  ('llm-inside-the-network', 1, 'architecture',
   '{"question": "Drag each part to its place in one training step.", "scenario": "During pretraining, the network sees a window of tokens from the dataset and has to predict the token that comes next. Then it learns from the right answer.", "noun": {"one": "part", "other": "parts"}, "slots": [{"id": "input", "label": "Input"}, {"id": "network", "label": "Model"}, {"id": "output", "label": "Output"}, {"id": "target", "label": "Right answer"}, {"id": "update", "label": "Learning step"}], "cards": [{"id": "a-database-of-facts", "label": "A database of facts"}, {"id": "nudge-the-parameters-toward-the-right-to", "label": "Nudge the parameters toward the right token"}, {"id": "a-person-typing-the-answer", "label": "A person typing the answer"}, {"id": "a-window-of-token-ids-from-the-data", "label": "A window of token IDs from the data"}, {"id": "the-token-that-actually-came-next", "label": "The token that actually came next"}, {"id": "a-neural-network-with-billions-of-parame", "label": "A neural network with billions of parameters"}, {"id": "a-search-engine-query", "label": "A search engine query"}, {"id": "a-probability-for-every-token-in-the-voc", "label": "A probability for every token in the vocabulary"}], "flows": [{"title": "Predict the next token", "stages": [["input"], ["network"], ["output"]]}, {"title": "Learn from the answer", "stages": [["output", "target"], ["update"]]}]}',
   '{"slots": {"input": "a-window-of-token-ids-from-the-data", "network": "a-neural-network-with-billions-of-parame", "output": "a-probability-for-every-token-in-the-voc", "target": "the-token-that-actually-came-next", "update": "nudge-the-parameters-toward-the-right-to"}}',
   'Tokens go in, and the network gives a probability for every possible next token. The real next token from the data is the right answer, and the parameters are nudged so that token gets a slightly higher probability next time.'),
  ('llm-inside-the-network', 2, 'multiple_choice',
   '{"question": "What does the network output for a position in the sequence?", "options": ["The ID of the web page the text came from", "A probability for every token in the vocabulary", "A yes or no answer", "One finished sentence"]}',
   '{"correct": 1}',
   'The output is a list of about 100,000 numbers, one per token in the vocabulary, saying how likely each one is to come next.'),
  ('llm-inside-the-network', 3, 'multiple_choice',
   '{"question": "What actually changes while the model trains?", "options": ["The number of layers in the network", "The tokens in its vocabulary", "The text of the training data", "The values of its parameters"]}',
   '{"correct": 3}',
   'Training only adjusts the parameters, the billions of numbers inside the network. The architecture, the vocabulary and the data stay the same.'),
  ('llm-inside-the-network', 4, 'multiple_choice',
   '{"question": "What is the context window?", "options": ["The list of websites the model was trained on", "The time limit for an answer", "The maximum number of tokens the network can look at at once", "The browser window where the chat runs"]}',
   '{"correct": 2}',
   'The network reads a limited window of tokens. Anything outside the window simply isn''t visible to it when it predicts the next token.'),
  ('llm-inside-the-network', 5, 'categorize',
   '{"question": "Which of these are chosen by the people designing the model, and which are learned in training?", "buckets": [{"id": "chosen-by-the-designers", "label": "Chosen by the designers"}, {"id": "learned-in-training", "label": "Learned in training"}], "items": [{"id": "the-size-of-the-context-window", "label": "The size of the context window"}, {"id": "which-next-tokens-the-model-finds-likely", "label": "Which next tokens the model finds likely"}, {"id": "the-tokenizer-s-vocabulary", "label": "The tokenizer''s vocabulary"}, {"id": "how-the-layers-of-the-network-are-connec", "label": "How the layers of the network are connected"}, {"id": "the-values-of-the-billions-of-parameters", "label": "The values of the billions of parameters"}]}',
   '{"items": {"how-the-layers-of-the-network-are-connec": "chosen-by-the-designers", "the-size-of-the-context-window": "chosen-by-the-designers", "the-tokenizer-s-vocabulary": "chosen-by-the-designers", "the-values-of-the-billions-of-parameters": "learned-in-training", "which-next-tokens-the-model-finds-likely": "learned-in-training"}}',
   'The designers fix the shape of the network, the context size and the tokenizer before training. Training then tunes the parameters, and those parameters decide which next tokens look likely.'),
  ('llm-inside-the-network', 6, 'multiple_choice',
   '{"question": "You send a 300-page manual to a model whose context window is much smaller than the manual. What happens?", "options": ["It learns the manual permanently for future chats", "It reads all of it, just more slowly", "It compresses the manual automatically without losing anything", "It can''t see the whole manual at once, so you need to split it or pick the relevant parts"]}',
   '{"correct": 3}',
   'Text beyond the context window doesn''t fit. APIs reject or cut it, so apps send only the relevant parts, for example with retrieval.'),
  ('llm-inference', 1, 'ordering',
   '{"question": "Put the steps of generating an answer in order.", "items": [{"id": "run-the-network-to-get-next-token-probab", "label": "Run the network to get next-token probabilities"}, {"id": "repeat-until-a-stop-token-or-a-length-li", "label": "Repeat until a stop token or a length limit"}, {"id": "sample-one-token-from-those-probabilitie", "label": "Sample one token from those probabilities"}, {"id": "add-the-token-to-the-end-of-the-sequence", "label": "Add the token to the end of the sequence"}, {"id": "turn-the-prompt-into-tokens", "label": "Turn the prompt into tokens"}]}',
   '{"order": ["turn-the-prompt-into-tokens", "run-the-network-to-get-next-token-probab", "sample-one-token-from-those-probabilitie", "add-the-token-to-the-end-of-the-sequence", "repeat-until-a-stop-token-or-a-length-li"]}',
   'Generation is a loop. The model predicts probabilities, one token is picked, it''s added to the text, and the longer text goes back in to predict the next token.'),
  ('llm-inference', 2, 'multiple_choice',
   '{"question": "You send the same prompt twice and get two different answers. Why?", "options": ["The model remembers it already answered and tries something new", "The tokenizer splits the prompt differently each time", "The model changed its parameters after the first answer", "Each next token is sampled from probabilities, so each run can take a different path"]}',
   '{"correct": 3}',
   'Inference is random by design. Picking a different token early on leads to a different continuation, even with the same prompt and the same model.'),
  ('llm-inference', 3, 'multiple_choice',
   '{"question": "What happens to the model''s parameters while you chat with it?", "options": ["They update once a day from all chats", "Nothing, they stay fixed and are only read", "They reset at the start of every chat", "They update after every message"]}',
   '{"correct": 1}',
   'Training is over when you use the model. During inference the parameters are fixed; only the text in the context changes.'),
  ('llm-inference', 4, 'categorize',
   '{"question": "Does each of these belong to training or to inference?", "buckets": [{"id": "training", "label": "Training"}, {"id": "inference", "label": "Inference"}], "items": [{"id": "picks-tokens-by-sampling-from-the-output", "label": "Picks tokens by sampling from the output"}, {"id": "compares-predictions-with-the-real-next-", "label": "Compares predictions with the real next token"}, {"id": "needs-a-huge-gpu-cluster-for-months", "label": "Needs a huge GPU cluster for months"}, {"id": "parameters-change-after-each-step", "label": "Parameters change after each step"}, {"id": "generates-text-one-token-at-a-time", "label": "Generates text one token at a time"}, {"id": "runs-every-time-a-user-sends-a-message", "label": "Runs every time a user sends a message"}]}',
   '{"items": {"parameters-change-after-each-step": "training", "needs-a-huge-gpu-cluster-for-months": "training", "compares-predictions-with-the-real-next-": "training", "runs-every-time-a-user-sends-a-message": "inference", "generates-text-one-token-at-a-time": "inference", "picks-tokens-by-sampling-from-the-output": "inference"}}',
   'Training is the long, expensive phase that tunes the parameters. Inference is what happens on every request: a fixed model generates tokens one by one.'),
  ('llm-inference', 5, 'multiple_choice',
   '{"question": "Why does generated text sound like its training data but rarely copies it word for word?", "options": ["The training data is deleted after training", "Sampling remixes the patterns the model learned instead of looking documents up", "The model checks every sentence against the internet", "The model is forbidden to use real sentences"]}',
   '{"correct": 1}',
   'The model doesn''t store and fetch documents. It produces new text that follows the statistics of what it saw, so the output is similar in style but usually not identical.'),
  ('llm-inference', 6, 'multiple_choice',
   '{"question": "A test checks that your LLM feature returns one exact sentence. It passes sometimes and fails sometimes. What''s the most likely reason?", "options": ["The API is returning cached answers from other users", "The output is sampled, so the wording varies between runs", "The model is learning from your test runs", "The test runner changes the prompt"]}',
   '{"correct": 1}',
   'Sampling makes LLM output vary. Test for meaning, structure or required fields instead of exact text, or reduce randomness where the API allows it.'),
  ('llm-training-gpt-2', 1, 'multiple_choice',
   '{"question": "GPT-2 came out in 2019. About how many parameters did its largest version have?", "options": ["About 16 thousand", "About 1.6 trillion", "About 1.6 billion", "About 1.6 million"]}',
   '{"correct": 2}',
   'GPT-2 had about 1.6 billion parameters (often rounded to 1.5 billion). Today''s large models have hundreds of billions or more.'),
  ('llm-training-gpt-2', 2, 'multiple_choice',
   '{"question": "How long was GPT-2''s context window?", "options": ["1,024 tokens", "Unlimited", "1 million tokens", "10 tokens"]}',
   '{"correct": 0}',
   'GPT-2 could look at 1,024 tokens at once. Modern models handle hundreds of thousands of tokens or more.'),
  ('llm-training-gpt-2', 3, 'multiple_choice',
   '{"question": "During training you watch a number called the loss. What do you want it to do?", "options": ["Go down, because the model is getting better at predicting the next token", "Go up, because the model is learning more", "Jump around as much as possible", "Stay exactly the same"]}',
   '{"correct": 0}',
   'The loss measures how wrong the next-token predictions are. A falling loss means the model gives higher probability to the tokens that really come next.'),
  ('llm-training-gpt-2', 4, 'categorize',
   '{"question": "What raises the cost of pretraining a model, and what lowers it?", "buckets": [{"id": "raises-the-cost", "label": "Raises the cost"}, {"id": "lowers-the-cost", "label": "Lowers the cost"}], "items": [{"id": "more-training-tokens", "label": "More training tokens"}, {"id": "software-that-keeps-the-gpus-busy", "label": "Software that keeps the GPUs busy"}, {"id": "faster-gpus", "label": "Faster GPUs"}, {"id": "more-parameters", "label": "More parameters"}, {"id": "training-for-more-steps", "label": "Training for more steps"}, {"id": "cleaner-better-datasets", "label": "Cleaner, better datasets"}]}',
   '{"items": {"more-parameters": "raises-the-cost", "more-training-tokens": "raises-the-cost", "training-for-more-steps": "raises-the-cost", "faster-gpus": "lowers-the-cost", "cleaner-better-datasets": "lowers-the-cost", "software-that-keeps-the-gpus-busy": "lowers-the-cost"}}',
   'Bigger models, more data and more steps all mean more computation. Faster hardware, better data and better software get the same result with less money.'),
  ('llm-training-gpt-2', 5, 'multiple_choice',
   '{"question": "Why is training done on GPUs?", "options": ["Training is a huge number of simple math operations that GPUs run in parallel", "GPUs check the model''s answers for mistakes", "GPUs store the training data permanently", "GPUs are the only chips that can read text"]}',
   '{"correct": 0}',
   'A training step is mostly large matrix multiplications. GPUs do thousands of these operations at the same time, which is why labs build huge GPU clusters.'),
  ('llm-training-gpt-2', 6, 'multiple_choice',
   '{"question": "Training GPT-2 cost about $40,000 in 2019. What did a similar run cost at the time of the video?", "options": ["A few hundred dollars or less", "About the same, $40,000", "Around $4 million", "It was no longer possible"]}',
   '{"correct": 0}',
   'Better data, faster GPUs and better software made the same training run hundreds of times cheaper in a few years.'),
  ('llm-training-gpt-2', 7, 'multiple_choice',
   '{"question": "Your manager asks if you could pretrain your own frontier-class model for a side project. What''s the realistic answer?", "options": ["No. That takes thousands of GPUs for months, so start from an existing model instead", "Yes, if you use a smaller tokenizer", "Yes, a laptop can do it over a weekend", "Yes, pretraining is cheap now, only fine-tuning is expensive"]}',
   '{"correct": 0}',
   'Small models like GPT-2 are now cheap to train, but frontier models still need enormous compute. For product work, you use or fine-tune existing models.'),
  ('llm-base-models', 1, 'multiple_choice',
   '{"question": "What is a base model?", "options": ["A small model used to test the tokenizer", "A helpful assistant that answers questions", "A search engine over its training data", "A document simulator: it continues any text with likely next tokens"]}',
   '{"correct": 3}',
   'Pretraining produces a base model. It has learned what internet text looks like and continues whatever you give it, but it wasn''t trained to act as an assistant.'),
  ('llm-base-models', 2, 'multiple_choice',
   '{"question": "You type \"What is 2 + 2?\" into a base model. What is most likely to happen?", "options": ["It answers \"4\" and stops, like an assistant", "It continues the text like a web page might, for example with more questions", "It refuses to answer", "It asks you what you mean"]}',
   '{"correct": 1}',
   'A base model doesn''t know it''s being asked something. It just continues the document, which could be a quiz page, a forum post or a list of questions.'),
  ('llm-base-models', 3, 'multiple_choice',
   '{"question": "You paste the opening sentence of a famous Wikipedia article into a base model, and it continues almost word for word. Why?", "options": ["The model looks the article up online", "It''s a coincidence", "The model has a copy of Wikipedia attached", "Popular high-quality pages appear many times in training, so the model memorized them"]}',
   '{"correct": 3}',
   'Text the model sees many times can end up memorized in its parameters. That''s called regurgitation, and it''s usually not what you want.'),
  ('llm-base-models', 4, 'multiple_choice',
   '{"question": "You ask a base model about something that happened after its training data was collected. What happens?", "options": ["It searches the web for the answer", "It refuses to continue", "It says it doesn''t know", "It makes up a plausible continuation, because it never saw those events"]}',
   '{"correct": 3}',
   'The model has no knowledge after its cutoff, but it still has to produce likely next tokens. So it writes something that sounds right, a confident guess.'),
  ('llm-base-models', 5, 'multiple_choice',
   '{"question": "Which prompt gets a base model to translate a new English word into Korean most reliably?", "options": ["\"You are a translator.\"", "Ten lines like \"apple: 사과\", followed by \"teacher:\"", "\"teacher\"", "\"Translate teacher into Korean please.\""]}',
   '{"correct": 1}',
   'A base model is great at continuing patterns. A list of examples (a few-shot prompt) makes the next line''s pattern obvious, so the likeliest continuation is the translation.'),
  ('llm-base-models', 6, 'categorize',
   '{"question": "Is each of these about a base model or an assistant model?", "buckets": [{"id": "base-model", "label": "Base model"}, {"id": "assistant-model", "label": "Assistant model"}], "items": [{"id": "was-fine-tuned-on-example-conversations", "label": "Was fine-tuned on example conversations"}, {"id": "is-the-direct-result-of-pretraining", "label": "Is the direct result of pretraining"}, {"id": "continues-any-text-with-likely-next-toke", "label": "Continues any text with likely next tokens"}, {"id": "declines-some-harmful-requests", "label": "Declines some harmful requests"}, {"id": "can-act-like-an-assistant-if-the-prompt-", "label": "Can act like an assistant if the prompt looks like a chat transcript"}, {"id": "answers-questions-in-a-helpful-chat-like", "label": "Answers questions in a helpful, chat-like way"}]}',
   '{"items": {"continues-any-text-with-likely-next-toke": "base-model", "is-the-direct-result-of-pretraining": "base-model", "can-act-like-an-assistant-if-the-prompt-": "base-model", "answers-questions-in-a-helpful-chat-like": "assistant-model", "was-fine-tuned-on-example-conversations": "assistant-model", "declines-some-harmful-requests": "assistant-model"}}',
   'The base model knows a lot but only continues documents. The assistant is the same knowledge after post-training on conversations, which gives it its helpful, safer behavior.'),
  ('llm-base-models', 7, 'multiple_choice',
   '{"question": "You need varied, natural-sounding forum posts to load-test your search feature, but an assistant model keeps writing in the same polite style. What could help?", "options": ["Asking the assistant to be polite", "Turning off tokenization", "A base model, prompted with a few real-looking example posts", "A bigger context window"]}',
   '{"correct": 2}',
   'Base models continue documents in their own style, so a few example posts produce many varied new ones. Assistants are tuned toward one helpful voice.'),
  ('llm-conversations-as-data', 1, 'multiple_choice',
   '{"question": "Post-training turns a base model into an assistant. What data does it train on?", "options": ["Example conversations: prompts with ideal assistant answers", "Lists of facts with no questions", "The chats of real users, without review", "More web pages, like in pretraining"]}',
   '{"correct": 0}',
   'The model keeps training, now on a dataset of conversations. It learns to answer in the way those example answers do.'),
  ('llm-conversations-as-data', 2, 'ordering',
   '{"question": "How does one conversation become training data? Put the steps in order.", "items": [{"id": "the-template-is-turned-into-one-sequence", "label": "The template is turned into one sequence of tokens"}, {"id": "the-model-is-trained-to-predict-the-assi", "label": "The model is trained to predict the assistant''s tokens"}, {"id": "the-conversation-is-wrapped-in-a-chat-te", "label": "The conversation is wrapped in a chat template with special tokens"}, {"id": "a-person-writes-a-prompt-and-an-ideal-an", "label": "A person writes a prompt and an ideal answer, following guidelines"}]}',
   '{"order": ["a-person-writes-a-prompt-and-an-ideal-an", "the-conversation-is-wrapped-in-a-chat-te", "the-template-is-turned-into-one-sequence", "the-model-is-trained-to-predict-the-assi"]}',
   'Conversations are written first, then formatted with special tokens that mark each turn, then tokenized. Training then works just like pretraining: predict the next token.'),
  ('llm-conversations-as-data', 3, 'multiple_choice',
   '{"question": "Why does a chat template add special tokens around each message?", "options": ["To mark where each turn starts and ends and who is speaking", "To tell the model which website the chat came from", "To make the text shorter", "To encrypt the conversation"]}',
   '{"correct": 0}',
   'The network only sees one long sequence of tokens. Special tokens mark the user and assistant turns, so the model knows when it''s its turn and when to stop.'),
  ('llm-conversations-as-data', 4, 'categorize',
   '{"question": "Is each of these about pretraining or post-training on conversations?", "buckets": [{"id": "pretraining", "label": "Pretraining"}, {"id": "post-training", "label": "Post-training"}], "items": [{"id": "can-take-hours-on-far-less-data", "label": "Can take hours, on far less data"}, {"id": "takes-months-on-thousands-of-gpus", "label": "Takes months on thousands of GPUs"}, {"id": "gives-the-model-most-of-its-knowledge", "label": "Gives the model most of its knowledge"}, {"id": "trains-on-example-conversations", "label": "Trains on example conversations"}, {"id": "trains-on-internet-documents", "label": "Trains on internet documents"}, {"id": "gives-the-model-its-assistant-style", "label": "Gives the model its assistant style"}]}',
   '{"items": {"trains-on-internet-documents": "pretraining", "takes-months-on-thousands-of-gpus": "pretraining", "gives-the-model-most-of-its-knowledge": "pretraining", "trains-on-example-conversations": "post-training", "can-take-hours-on-far-less-data": "post-training", "gives-the-model-its-assistant-style": "post-training"}}',
   'Pretraining is the big, expensive step that builds knowledge. Post-training is much smaller and cheaper, and it shapes how the model behaves and responds.'),
  ('llm-conversations-as-data', 5, 'multiple_choice',
   '{"question": "The people who write example answers follow guidelines such as being helpful, truthful and harmless. What does that mean for the answers you get?", "options": ["The guidelines are only used for marketing", "Every answer was checked by a person before you see it", "The assistant imitates how a skilled person following those guidelines would answer", "The assistant has its own opinions on what''s helpful"]}',
   '{"correct": 2}',
   'The assistant learned from examples written under those guidelines. Its answers are a statistical imitation of that kind of person, not a person checking your specific answer.'),
  ('llm-conversations-as-data', 6, 'multiple_choice',
   '{"question": "Where does most of the conversation data for modern assistants come from?", "options": ["Copied from public chat apps", "Mostly generated by LLMs, then checked and edited by people", "Only written by hand by human labelers", "Generated at random"]}',
   '{"correct": 1}',
   'Early datasets were written by hand. Today, models draft much of the data and people review and fix it, which makes it possible to build very large datasets.'),
  ('llm-conversations-as-data', 7, 'multiple_choice',
   '{"question": "Your company wants its internal assistant to always answer in short bullet points with links to the wiki. What''s the post-training way to get that?", "options": ["Fine-tune it on many example conversations that answer in that format", "Add more web pages to the training data", "Pretrain a new model from scratch", "Make the context window larger"]}',
   '{"correct": 0}',
   'Post-training teaches style and format through examples. A set of conversations written the way you want is the direct way to change how the assistant answers.'),
  ('llm-hallucinations-and-tools', 1, 'multiple_choice',
   '{"question": "You ask an assistant about a person who doesn''t exist, and it writes a confident biography. Why?", "options": ["The tokenizer mixed up the name", "It''s lying on purpose", "It learned the confident style of answers in its training, even for things it doesn''t know", "It found a real person with that name online"]}',
   '{"correct": 2}',
   'In the training conversations, questions like that are answered confidently. Without special training, the model copies that style, even when it has nothing to base the answer on.'),
  ('llm-hallucinations-and-tools', 2, 'multiple_choice',
   '{"question": "How can model makers teach a model to say \"I don''t know\"?", "options": ["Make the model bigger until it knows everything", "Remove all hard questions from the training data", "Find questions it gets wrong by testing it, and train on examples where the answer is \"I don''t know\"", "Tell users to ask simpler questions"]}',
   '{"correct": 2}',
   'You can probe what the model actually knows. Where it keeps getting things wrong, you add training examples that refuse to guess, so it learns to link its own uncertainty to saying so.'),
  ('llm-hallucinations-and-tools', 3, 'system_builder',
   '{"question": "Build an assistant that can look things up: add the parts you need and connect them.", "scenario": "The assistant should search the web instead of guessing. When it needs facts, the model writes a search query, your app runs it, and the results go back into the model''s context before it answers.", "noun": {"one": "part", "other": "parts"}, "nodes": [{"id": "search", "label": "Search tool", "role": "Runs the query"}, {"id": "image-generator", "label": "Image generator", "role": "Creates pictures"}, {"id": "gpu-cluster", "label": "GPU cluster", "role": "Pretrains the model"}, {"id": "llm", "label": "Language model", "role": "Writes answers and queries"}, {"id": "tokenizer-trainer", "label": "Tokenizer trainer", "role": "Builds a new vocabulary"}, {"id": "chat-app", "label": "Chat app", "role": "Sends messages, shows answers"}, {"id": "context", "label": "Context window", "role": "Holds the chat and the results"}]}',
   '{"nodes": ["chat-app", "context", "llm", "search"], "connections": [{"from": "chat-app", "to": "context"}, {"from": "context", "to": "llm"}, {"from": "llm", "to": "search"}, {"from": "search", "to": "context"}, {"from": "llm", "to": "chat-app"}]}',
   'The user''s message goes into the context, and the model reads it. When it needs facts, it writes a query, the search tool runs it and the results are added to the context. The model then answers from text it can actually see.'),
  ('llm-hallucinations-and-tools', 4, 'multiple_choice',
   '{"question": "When a model uses a search tool, where do the search results go?", "options": ["Straight to the user, without the model seeing them", "Into the context window, where the model can read them while it answers", "Into the model''s parameters, permanently", "Into the tokenizer''s vocabulary"]}',
   '{"correct": 1}',
   'Tool results are pasted into the conversation. The model reads them like any other text in its context, which is far more reliable than recalling facts from its parameters.'),
  ('llm-hallucinations-and-tools', 5, 'multiple_choice',
   '{"question": "Which question is a model without tools most likely to answer with made-up facts?", "options": ["\"What is the capital of France?\"", "\"What did the mayor of a small town say at last week''s council meeting?\"", "\"Write a short poem about the sea.\"", "\"Explain what a for loop does.\""]}',
   '{"correct": 1}',
   'Obscure, specific and recent facts are the riskiest. The model likely never saw them, but it will still produce a fluent answer.'),
  ('llm-hallucinations-and-tools', 6, 'multiple_choice',
   '{"question": "Your support bot invents return policies that don''t exist. Which fix targets the cause?", "options": ["Make its answers shorter", "Ask users to rephrase their questions", "Put the real policy documents into the context, and tell it to say when the answer isn''t there", "Ask it to answer more confidently"]}',
   '{"correct": 2}',
   'The bot guesses because the policies aren''t in front of it. Giving it the real documents, plus permission to say "I don''t know", removes the reason to make things up.'),
  ('llm-knowledge-vs-memory', 1, 'multiple_choice',
   '{"question": "What is knowledge stored in the model''s parameters most like?", "options": ["A vague memory of something you read a long time ago", "Notes you''re looking at right now", "A perfect copy of every web page", "A database you can query exactly"]}',
   '{"correct": 0}',
   'Pretraining compresses a huge amount of text into the parameters. What''s left is a fuzzy recollection: good for common things, unreliable for details.'),
  ('llm-knowledge-vs-memory', 2, 'multiple_choice',
   '{"question": "What is text in the context window most like?", "options": ["A new part of the model''s parameters", "Background noise the model ignores", "Working memory: the model can use it directly and precisely", "Long-term memory that lasts after the chat"]}',
   '{"correct": 2}',
   'Everything in the context is directly available while the model generates. That''s why answers about text you paste in are much more accurate.'),
  ('llm-knowledge-vs-memory', 3, 'categorize',
   '{"question": "Where does each kind of information live?", "buckets": [{"id": "in-the-parameters-vague-memory", "label": "In the parameters (vague memory)"}, {"id": "in-the-context-window-working-memory", "label": "In the context window (working memory)"}], "items": [{"id": "search-results-a-tool-just-returned", "label": "Search results a tool just returned"}, {"id": "a-general-sense-of-grammar-and-style", "label": "A general sense of grammar and style"}, {"id": "earlier-messages-in-this-conversation", "label": "Earlier messages in this conversation"}, {"id": "facts-from-web-pages-seen-in-pretraining", "label": "Facts from web pages seen in pretraining"}, {"id": "a-document-you-paste-into-the-chat", "label": "A document you paste into the chat"}, {"id": "a-famous-book-it-read-many-times-in-trai", "label": "A famous book it read many times in training"}]}',
   '{"items": {"facts-from-web-pages-seen-in-pretraining": "in-the-parameters-vague-memory", "a-general-sense-of-grammar-and-style": "in-the-parameters-vague-memory", "a-famous-book-it-read-many-times-in-trai": "in-the-parameters-vague-memory", "a-document-you-paste-into-the-chat": "in-the-context-window-working-memory", "earlier-messages-in-this-conversation": "in-the-context-window-working-memory", "search-results-a-tool-just-returned": "in-the-context-window-working-memory"}}',
   'Anything learned in training lives in the parameters. Anything in the current conversation, including pasted text and tool results, sits in the context window.'),
  ('llm-knowledge-vs-memory', 4, 'multiple_choice',
   '{"question": "You want a good summary of chapter 3 of a book. What gives the best result?", "options": ["Ask the model to guess what chapter 3 is about", "Paste the chapter into the prompt and ask for a summary", "Ask for a summary of the whole book", "Ask for a summary of chapter 3 from memory"]}',
   '{"correct": 1}',
   'With the chapter in the context, the model works from the actual text, not from a vague memory of it.'),
  ('llm-knowledge-vs-memory', 5, 'multiple_choice',
   '{"question": "You ask a model about functions in your company''s private library, and it invents some that don''t exist. What''s the fix?", "options": ["Tell the model the library is important", "Ask the same question more politely", "Put the library''s real docs or source code into the context", "Use a model with more parameters"]}',
   '{"correct": 2}',
   'The model never saw your private code in training, so it can only guess. Giving it the real code turns guessing into reading.'),
  ('llm-knowledge-of-self', 1, 'multiple_choice',
   '{"question": "You ask an open model \"Who made you?\" and it says it''s ChatGPT by OpenAI, but it isn''t. Why?", "options": ["It looked up the answer online", "It was secretly made by OpenAI", "It''s trying to trick you", "Without training data about itself, it gives the most common answer it saw on the internet"]}',
   '{"correct": 3}',
   'The model has no built-in sense of identity. If its makers didn''t teach it one, it falls back on what is statistically likely, and the internet talks about ChatGPT a lot.'),
  ('llm-knowledge-of-self', 2, 'multiple_choice',
   '{"question": "Does a model remember you between separate chats?", "options": ["Only if you mention your name", "Yes, it learns from every chat", "Yes, but only for paying users", "Not by itself. Each chat starts from the same fixed parameters, unless the app adds memory to the context"]}',
   '{"correct": 3}',
   'The parameters don''t change while you chat. Any memory features work by putting saved notes back into the context of a new chat.'),
  ('llm-knowledge-of-self', 3, 'multiple_choice',
   '{"question": "How do model makers give a model the right name and creator?", "options": ["It reads its own source code", "They train it on conversations about its identity, or put that information in a system message", "They can''t, it''s random", "The model picks a name during pretraining"]}',
   '{"correct": 1}',
   'Identity is added on purpose: either with example conversations about who the assistant is, or with hidden instructions at the start of each chat.'),
  ('llm-knowledge-of-self', 4, 'multiple_choice',
   '{"question": "What''s the best way to think about an LLM''s \"self\"?", "options": ["It''s a person who lives inside the computer", "It''s a copy of the people who wrote its training data", "It''s the same as the company that made it", "There''s no lasting self. It generates each answer from its parameters and the current context"]}',
   '{"correct": 3}',
   'An LLM is a token predictor that starts fresh with every conversation. Its "personality" is a pattern learned in training, not a continuous being.'),
  ('llm-knowledge-of-self', 5, 'multiple_choice',
   '{"question": "You build a support assistant on an open model and want it to introduce itself as \"Ada from Acme\". What''s the simplest way?", "options": ["Put the name and role in the system message of every conversation", "Pretrain the model on Acme''s website", "Ask users to call it Ada", "Rename the model file"]}',
   '{"correct": 0}',
   'A system message is in the context of every chat, so the model reliably uses that identity. Fine-tuning works too, but it''s far more effort.'),
  ('llm-tokens-to-think', 1, 'multiple_choice',
   '{"question": "Why can''t a model do a lot of reasoning while producing a single token?", "options": ["The model is not allowed to think", "Reasoning only happens during training", "Each token gets the same, limited amount of computation", "Tokens are too short to hold numbers"]}',
   '{"correct": 2}',
   'Producing one token is one pass through the network, with a fixed amount of computation. Hard problems need that work spread over many tokens.'),
  ('llm-tokens-to-think', 2, 'multiple_choice',
   '{"question": "Sam buys 4 notebooks and 3 pens for $19. A pen costs $1. Which example answer is better to train a model on?", "options": ["\"$4.\"", "\"The pens cost 3 × $1 = $3. That leaves $19 − $3 = $16 for the notebooks, so each costs $16 ÷ 4 = $4.\"", "\"Each notebook costs $4. The pens cost $3, so the notebooks cost $16, and $16 ÷ 4 = $4.\"", "\"Notebooks usually cost about $4.\""]}',
   '{"correct": 1}',
   'Working first and answering last lets the model build up the result over many tokens. Stating the answer first forces it to compute everything in one token, and the explanation afterwards can''t fix a wrong guess.'),
  ('llm-tokens-to-think', 3, 'ordering',
   '{"question": "Put this worked solution in a good order for a model to learn from.", "scenario": "Sam buys 4 notebooks and 3 pens for $19 in total. A pen costs $1. How much is one notebook?", "items": [{"id": "subtract-it-from-the-total-19-3-16", "label": "Subtract it from the total: $19 − $3 = $16"}, {"id": "split-the-rest-among-the-notebooks-16-4-", "label": "Split the rest among the notebooks: $16 ÷ 4 = $4"}, {"id": "state-the-answer-one-notebook-costs-4", "label": "State the answer: one notebook costs $4"}, {"id": "work-out-the-cost-of-the-pens-3-1-3", "label": "Work out the cost of the pens: 3 × $1 = $3"}]}',
   '{"order": ["work-out-the-cost-of-the-pens-3-1-3", "subtract-it-from-the-total-19-3-16", "split-the-rest-among-the-notebooks-16-4-", "state-the-answer-one-notebook-costs-4"]}',
   'Each step only needs a little computation and builds on the one before. The final answer comes last, when all the work is already in the context.'),
  ('llm-tokens-to-think', 4, 'categorize',
   '{"question": "Which tasks can you just ask for, and which should the model solve with code?", "buckets": [{"id": "just-ask", "label": "Just ask"}, {"id": "ask-it-to-use-code", "label": "Ask it to use code"}], "items": [{"id": "count-how-often-error-appears-in-a-5-000", "label": "Count how often \"error\" appears in a 5,000-line log"}, {"id": "multiply-two-9-digit-numbers", "label": "Multiply two 9-digit numbers"}, {"id": "suggest-names-for-a-new-feature", "label": "Suggest names for a new feature"}, {"id": "explain-what-a-rest-api-is", "label": "Explain what a REST API is"}, {"id": "add-up-40-prices-from-a-table", "label": "Add up 40 prices from a table"}, {"id": "summarize-a-short-email", "label": "Summarize a short email"}]}',
   '{"items": {"explain-what-a-rest-api-is": "just-ask", "suggest-names-for-a-new-feature": "just-ask", "summarize-a-short-email": "just-ask", "multiply-two-9-digit-numbers": "ask-it-to-use-code", "count-how-often-error-appears-in-a-5-000": "ask-it-to-use-code", "add-up-40-prices-from-a-table": "ask-it-to-use-code"}}',
   'Language tasks suit the model well. Exact calculations and counting are where mental math in tokens breaks down, and code gets them exactly right.'),
  ('llm-tokens-to-think', 5, 'multiple_choice',
   '{"question": "Why is it more reliable to let the model use a code tool for arithmetic?", "options": ["Code is shorter than text, so it''s cheaper", "The model is not allowed to do math in text", "Code makes the model''s parameters bigger", "The code runs exactly, instead of the model doing mental math in a few tokens"]}',
   '{"correct": 3}',
   'The model writes the code, and an interpreter runs it with exact results. That moves the hard part to a tool that can''t make arithmetic slips.'),
  ('llm-tokens-to-think', 6, 'multiple_choice',
   '{"question": "Your app asks the model to return only the final number for a multi-step pricing question, and it''s often wrong. What should you change?", "options": ["Ask for the answer in bold", "Let it reason step by step or use code first, then pick out the final number", "Use a shorter prompt", "Ask it to answer faster"]}',
   '{"correct": 1}',
   'Forcing an instant answer leaves no tokens for the work. Let the model show its steps (or call code), then parse the result in your code.'),
  ('llm-jagged-intelligence', 1, 'multiple_choice',
   '{"question": "Why do models often miscount the letters in a word like \"strawberry\"?", "options": ["The word is too long for the context window", "Counting is turned off in chat", "They never saw the word in training", "They see tokens, chunks of characters, not individual letters"]}',
   '{"correct": 3}',
   '"strawberry" is only a few tokens for the model. It never looks at the letters one by one, so letter-level questions are surprisingly hard for it.'),
  ('llm-jagged-intelligence', 2, 'multiple_choice',
   '{"question": "A model solves a hard coding problem but then says 9.11 is bigger than 9.9. What''s the best way to think about this?", "options": ["It only fails when the internet is slow", "The model is lying on purpose", "Its abilities are jagged: very strong in places, with surprising holes, so check its work", "The model is broken and shouldn''t be used"]}',
   '{"correct": 2}',
   'LLM skills don''t grow evenly like a person''s. They can be brilliant at hard tasks and fail at easy ones, so treat them as powerful tools whose output you verify.'),
  ('llm-jagged-intelligence', 3, 'categorize',
   '{"question": "Which tasks is a model likely to handle well, and which might trip it up?", "buckets": [{"id": "likely-fine", "label": "Likely fine"}, {"id": "likely-to-trip-it-up", "label": "Likely to trip it up"}], "items": [{"id": "count-the-letters-in-a-long-word", "label": "Count the letters in a long word"}, {"id": "compare-decimals-like-9-11-and-9-9", "label": "Compare decimals like 9.11 and 9.9"}, {"id": "explain-the-difference-between-a-list-an", "label": "Explain the difference between a list and a set"}, {"id": "reverse-the-characters-of-a-string", "label": "Reverse the characters of a string"}, {"id": "translate-a-common-phrase-into-spanish", "label": "Translate a common phrase into Spanish"}, {"id": "rewrite-a-paragraph-in-a-friendlier-tone", "label": "Rewrite a paragraph in a friendlier tone"}]}',
   '{"items": {"rewrite-a-paragraph-in-a-friendlier-tone": "likely-fine", "explain-the-difference-between-a-list-an": "likely-fine", "translate-a-common-phrase-into-spanish": "likely-fine", "count-the-letters-in-a-long-word": "likely-to-trip-it-up", "reverse-the-characters-of-a-string": "likely-to-trip-it-up", "compare-decimals-like-9-11-and-9-9": "likely-to-trip-it-up"}}',
   'Tasks about meaning and language play to the model''s strengths. Tasks about individual characters or exact comparisons hit the limits of tokens and single-token reasoning.'),
  ('llm-jagged-intelligence', 4, 'multiple_choice',
   '{"question": "What''s a reliable way to get a character-level task right, like counting letters?", "options": ["Ask it to think harder in one word", "Write the question in capital letters", "Ask the model to solve it with a short piece of code", "Ask the same question several times"]}',
   '{"correct": 2}',
   'Code works on actual characters, so a tiny script gives the exact answer. The model just has to write the code, which it''s good at.'),
  ('llm-jagged-intelligence', 5, 'multiple_choice',
   '{"question": "Your app uses an LLM to check that user IDs have exactly 12 characters, and some wrong IDs get through. What should you do?", "options": ["Check the length in normal code, and use the model only where you need language understanding", "Send each ID twice", "Use a model with a bigger context window", "Ask the model to be more careful"]}',
   '{"correct": 0}',
   'Exact rules belong in deterministic code. Use the LLM for fuzzy language tasks, and don''t rely on it for character counting.'),
  ('llm-why-rl', 1, 'architecture',
   '{"question": "Drag each training stage to the part of a textbook it works like.", "scenario": "A good textbook teaches in three ways: it explains the topic, it shows worked examples, and it gives practice problems with the answers at the back. Training an LLM follows the same idea.", "noun": {"one": "stage", "other": "stages"}, "slots": [{"id": "explain", "label": "Explanations that cover the topic"}, {"id": "worked", "label": "Worked examples with full solutions"}, {"id": "practice", "label": "Practice problems with only the final answer"}], "cards": [{"id": "pretraining", "label": "Pretraining"}, {"id": "inference", "label": "Inference"}, {"id": "supervised-fine-tuning", "label": "Supervised fine-tuning"}, {"id": "tokenization", "label": "Tokenization"}, {"id": "reinforcement-learning", "label": "Reinforcement learning"}], "flows": [{"title": "How you learn from a textbook", "stages": [["explain"], ["worked"], ["practice"]]}]}',
   '{"slots": {"explain": "pretraining", "worked": "supervised-fine-tuning", "practice": "reinforcement-learning"}}',
   'Pretraining is like reading the explanations: broad knowledge. Supervised fine-tuning is like studying an expert''s worked examples. Reinforcement learning is like doing practice problems: you try, check the answer and learn what works.'),
  ('llm-why-rl', 2, 'multiple_choice',
   '{"question": "What can''t supervised fine-tuning teach well on its own?", "options": ["How to answer in a conversation", "How to use the chat template", "What a helpful answer looks like", "Which way of solving a problem works best for the model itself"]}',
   '{"correct": 3}',
   'Fine-tuning copies human-written solutions. It can''t find out which reasoning steps actually work best for the model''s own way of processing tokens.'),
  ('llm-why-rl', 3, 'multiple_choice',
   '{"question": "What do practice problems give a learner that worked examples don''t?", "options": ["A full solution to copy", "The chance to try their own approach and check it against the answer", "A shorter textbook", "More background explanations"]}',
   '{"correct": 1}',
   'With practice problems, you find your own path to the answer. That''s what reinforcement learning gives the model.'),
  ('llm-why-rl', 4, 'multiple_choice',
   '{"question": "In what order are the training stages of a modern LLM usually run?", "options": ["All three at the same time", "Pretraining, then supervised fine-tuning, then reinforcement learning", "Fine-tuning, then pretraining, then reinforcement learning", "Reinforcement learning, then pretraining, then fine-tuning"]}',
   '{"correct": 1}',
   'Each stage builds on the previous one: knowledge first, then the assistant format, then practice that sharpens problem solving.'),
  ('llm-why-rl', 5, 'multiple_choice',
   '{"question": "You want a model that''s better at your team''s tricky SQL puzzles, and you can automatically check whether a query returns the right rows. Which training approach fits best?", "options": ["More pretraining on random web pages", "Reinforcement learning: let it try many queries and reward the ones that return the right rows", "Removing the chat template", "A bigger tokenizer"]}',
   '{"correct": 1}',
   'An automatic check of the answer is exactly what RL needs. The model can practice many attempts and learn from the ones that work.'),
  ('llm-how-rl-works', 1, 'ordering',
   '{"question": "Put the steps of the reinforcement learning loop in order.", "items": [{"id": "train-the-model-on-the-solutions-that-wo", "label": "Train the model on the solutions that worked"}, {"id": "check-which-solutions-reach-the-right-an", "label": "Check which solutions reach the right answer"}, {"id": "give-the-model-a-problem-with-a-known-an", "label": "Give the model a problem with a known answer"}, {"id": "repeat-with-many-more-problems", "label": "Repeat with many more problems"}, {"id": "let-it-write-many-different-solutions", "label": "Let it write many different solutions"}]}',
   '{"order": ["give-the-model-a-problem-with-a-known-an", "let-it-write-many-different-solutions", "check-which-solutions-reach-the-right-an", "train-the-model-on-the-solutions-that-wo", "repeat-with-many-more-problems"]}',
   'The model practices: it tries a problem many times, the attempts are checked, and the successful ones are reinforced so they become more likely. Over many problems, it gets better at solving them.'),
  ('llm-how-rl-works', 2, 'multiple_choice',
   '{"question": "Why not just train on solutions written by human experts?", "options": ["What''s easy for a person isn''t always easy for the model, so human solutions may skip steps it needs", "Experts refuse to write solutions", "Human text can''t be tokenized", "Human solutions are always wrong"]}',
   '{"correct": 0}',
   'People and models find different things hard. RL lets the model find token sequences that work for it, instead of copying a path that suits a human.'),
  ('llm-how-rl-works', 3, 'multiple_choice',
   '{"question": "Where does reinforcement learning get its learning signal from?", "options": ["From the size of the answer", "From a person writing each solution", "From more internet text", "From checking whether the final answer is right"]}',
   '{"correct": 3}',
   'Nobody writes the solutions in RL. The only signal is whether an attempt reached the right result.'),
  ('llm-how-rl-works', 4, 'multiple_choice',
   '{"question": "What does it mean that a task is \"verifiable\"?", "options": ["It has a long explanation", "Only experts can solve it", "It was checked by the government", "Its answer can be checked automatically, like a math result or passing tests"]}',
   '{"correct": 3}',
   'Verifiable tasks have answers you can check without a person, which makes them ideal for RL practice at scale.'),
  ('llm-how-rl-works', 5, 'multiple_choice',
   '{"question": "You want to use RL to make a model better at writing code. What can serve as the reward?", "options": ["Whether the generated code passes the unit tests", "How many comments the code has", "How long the code is", "Whether the code uses a popular library"]}',
   '{"correct": 0}',
   'Passing tests is an automatic, meaningful check of whether the code works. That''s the kind of reward RL needs.'),
  ('llm-thinking-models', 1, 'multiple_choice',
   '{"question": "During RL on math problems, as in the DeepSeek-R1 paper, what appeared without anyone teaching it?", "options": ["Answers in a new language", "Longer answers in which the model re-checks its steps and tries other approaches", "Shorter answers with only the final number", "Answers that copy textbook solutions word for word"]}',
   '{"correct": 1}',
   'As RL went on, answers got longer and more accurate. The model learned on its own to check its work, backtrack and try again, which is what we now call thinking.'),
  ('llm-thinking-models', 2, 'multiple_choice',
   '{"question": "Why do thinking models write long chains of thought before answering?", "options": ["They are trained to fill the context window", "To hide the answer from the user", "More tokens mean more computation, and trying, checking and backtracking leads to right answers", "Longer answers cost the user more"]}',
   '{"correct": 2}',
   'RL rewarded whatever reached the right answer. Spending more tokens on exploring and checking turned out to work, so the model learned to do it.'),
  ('llm-thinking-models', 3, 'categorize',
   '{"question": "When is a thinking model worth it, and when is a fast regular model fine?", "buckets": [{"id": "use-a-thinking-model", "label": "Use a thinking model"}, {"id": "a-regular-model-is-fine", "label": "A regular model is fine"}], "items": [{"id": "debug-a-tricky-race-condition", "label": "Debug a tricky race condition"}, {"id": "plan-a-multi-step-data-migration", "label": "Plan a multi-step data migration"}, {"id": "write-a-friendly-reply-to-a-customer", "label": "Write a friendly reply to a customer"}, {"id": "look-up-the-syntax-of-a-common-function", "label": "Look up the syntax of a common function"}, {"id": "fix-a-typo-in-a-readme", "label": "Fix a typo in a README"}, {"id": "prove-a-math-statement", "label": "Prove a math statement"}]}',
   '{"items": {"debug-a-tricky-race-condition": "use-a-thinking-model", "prove-a-math-statement": "use-a-thinking-model", "plan-a-multi-step-data-migration": "use-a-thinking-model", "fix-a-typo-in-a-readme": "a-regular-model-is-fine", "write-a-friendly-reply-to-a-customer": "a-regular-model-is-fine", "look-up-the-syntax-of-a-common-function": "a-regular-model-is-fine"}}',
   'Thinking pays off on problems that need careful reasoning. For simple or knowledge-based questions, a regular model answers just as well, faster and cheaper.'),
  ('llm-thinking-models', 4, 'multiple_choice',
   '{"question": "What''s the trade-off of using a thinking model?", "options": ["There''s no trade-off", "Better on hard problems, but slower and more expensive, because it writes many more tokens", "Cheaper, but only works in English", "Faster, but less accurate"]}',
   '{"correct": 1}',
   'All the thinking is extra tokens. You pay for them in time and money, so use thinking where it matters.'),
  ('llm-thinking-models', 5, 'multiple_choice',
   '{"question": "Your chat feature uses a thinking model for every message, and users complain it''s slow on simple questions. What''s a good fix?", "options": ["Ask users to type faster", "Make the thinking model think for longer", "Send simple questions to a regular model and keep the thinking model for hard ones", "Remove the chat history"]}',
   '{"correct": 2}',
   'Routing by difficulty gives quick answers for easy questions and careful reasoning where it''s needed.'),
  ('llm-alphago', 1, 'multiple_choice',
   '{"question": "What happened when AlphaGo was trained only by imitating expert human games?", "options": ["It couldn''t learn to play at all", "It beat every human right away", "It only learned the opening moves", "It became strong, but leveled off below the best human players"]}',
   '{"correct": 3}',
   'Imitation can get you close to the people you copy, but rarely past them. The examples set the ceiling.'),
  ('llm-alphago', 2, 'multiple_choice',
   '{"question": "What let AlphaGo beat the world''s best players?", "options": ["A bigger board", "Help from human players during matches", "Reinforcement learning: playing many games against itself and learning which moves led to wins", "Studying even more human games"]}',
   '{"correct": 2}',
   'Winning or losing is easy to check in Go. Self-play with RL let the system practice far beyond the human examples.'),
  ('llm-alphago', 3, 'multiple_choice',
   '{"question": "Why is AlphaGo''s \"move 37\" against Lee Sedol famous?", "options": ["It was the first move of the game", "Experts thought a human would almost never play it, yet it turned out to be strong", "A human told the system to play it", "It broke the rules of Go"]}',
   '{"correct": 1}',
   'RL found a move outside human habits that turned out to be brilliant. It showed that practice can discover strategies people never thought of.'),
  ('llm-alphago', 4, 'multiple_choice',
   '{"question": "What does AlphaGo suggest about LLMs trained with RL?", "options": ["They only work for board games", "They might discover ways of reasoning no person wrote down", "They no longer need any data", "They will always stay below human level"]}',
   '{"correct": 1}',
   'If RL can go beyond imitation in Go, RL on reasoning tasks could also find new, better ways to solve problems, not only copy ours.'),
  ('llm-alphago', 5, 'multiple_choice',
   '{"question": "Your team wants to use RL to make a model write better marketing slogans. What''s the main obstacle compared with Go?", "options": ["Models can''t write slogans", "RL only works on numbers", "There''s no automatic way to score a slogan as right or wrong", "Slogans are too short to tokenize"]}',
   '{"correct": 2}',
   'Go has a clear winner. Slogan quality is a matter of taste, so you need another way to get a reward, which is what RLHF is for.'),
  ('llm-rlhf', 1, 'categorize',
   '{"question": "Which tasks can be checked automatically, and which can''t?", "buckets": [{"id": "verifiable", "label": "Verifiable"}, {"id": "not-verifiable", "label": "Not verifiable"}], "items": [{"id": "find-the-shortest-route-in-a-graph", "label": "Find the shortest route in a graph"}, {"id": "write-a-funny-joke", "label": "Write a funny joke"}, {"id": "summarize-an-article-well", "label": "Summarize an article well"}, {"id": "write-a-poem-about-autumn", "label": "Write a poem about autumn"}, {"id": "solve-an-equation", "label": "Solve an equation"}, {"id": "make-all-unit-tests-pass", "label": "Make all unit tests pass"}]}',
   '{"items": {"solve-an-equation": "verifiable", "make-all-unit-tests-pass": "verifiable", "find-the-shortest-route-in-a-graph": "verifiable", "write-a-funny-joke": "not-verifiable", "summarize-an-article-well": "not-verifiable", "write-a-poem-about-autumn": "not-verifiable"}}',
   'Some tasks have a checkable right answer. Others depend on human taste, and there RL needs a different kind of reward.'),
  ('llm-rlhf', 2, 'ordering',
   '{"question": "Put the steps of reinforcement learning from human feedback (RLHF) in order.", "items": [{"id": "the-model-writes-several-answers-to-a-pr", "label": "The model writes several answers to a prompt"}, {"id": "people-rank-the-answers-from-best-to-wor", "label": "People rank the answers from best to worst"}, {"id": "the-model-is-trained-with-rl-to-get-high", "label": "The model is trained with RL to get high scores from the reward model"}, {"id": "a-reward-model-learns-to-predict-those-r", "label": "A reward model learns to predict those rankings"}]}',
   '{"order": ["the-model-writes-several-answers-to-a-pr", "people-rank-the-answers-from-best-to-wor", "a-reward-model-learns-to-predict-those-r", "the-model-is-trained-with-rl-to-get-high"]}',
   'People can''t score millions of answers by hand. So they rank a smaller set, a reward model learns to imitate their judgment, and RL then runs against that reward model.'),
  ('llm-rlhf', 3, 'multiple_choice',
   '{"question": "Why do people rank answers instead of writing perfect ones?", "options": ["Ranking is much easier than writing, so you get more and better data", "The model can''t learn from written answers", "Writing answers is not allowed", "Rankings take up fewer tokens"]}',
   '{"correct": 0}',
   'Most people can''t write a great joke on demand, but almost anyone can tell which of five jokes is funniest. Comparing is the easier job.'),
  ('llm-rlhf', 4, 'system_builder',
   '{"question": "Build the RLHF training setup: add the parts you need and connect them.", "scenario": "You want the model to write better jokes, which can''t be checked automatically. People rank some of the model''s answers. A reward model learns from their rankings and then scores the model''s answers during RL.", "noun": {"one": "part", "other": "parts"}, "nodes": [{"id": "language-model", "label": "Language model", "role": "Writes candidate answers"}, {"id": "reward-model", "label": "Reward model", "role": "Predicts the rankings"}, {"id": "raters", "label": "Human raters", "role": "Rank some answers"}, {"id": "web-crawler", "label": "Web crawler", "role": "Collects web pages"}, {"id": "rl-trainer", "label": "RL trainer", "role": "Updates the language model"}, {"id": "tokenizer", "label": "Tokenizer", "role": "Splits text into tokens"}, {"id": "unit-tests", "label": "Unit tests", "role": "Check code automatically"}]}',
   '{"nodes": ["language-model", "raters", "reward-model", "rl-trainer"], "connections": [{"from": "language-model", "to": "raters"}, {"from": "raters", "to": "reward-model"}, {"from": "language-model", "to": "reward-model"}, {"from": "reward-model", "to": "rl-trainer"}, {"from": "rl-trainer", "to": "language-model"}]}',
   'The model''s answers go to people, whose rankings train the reward model. During RL, the reward model scores new answers, and the trainer updates the language model toward higher scores. No unit tests here: jokes can''t be checked automatically.'),
  ('llm-rlhf', 5, 'multiple_choice',
   '{"question": "Why can''t RLHF run for as long as RL on math problems?", "options": ["Jokes run out", "People get tired of ranking", "The GPUs overheat", "The model learns to game the reward model, finding odd answers that score high but aren''t good"]}',
   '{"correct": 3}',
   'A reward model is only an imitation of human judgment, and it has blind spots. Optimize against it for too long and the model finds them, so RLHF is run only briefly.'),
  ('llm-rlhf', 6, 'multiple_choice',
   '{"question": "Your team trains a model with RLHF. After many more steps, answers get weirder while the reward scores keep rising. What''s happening?", "options": ["The model is getting better and the answers just look weird", "The tokenizer broke", "The human raters changed their minds", "The model is exploiting the reward model, so you should stop training earlier"]}',
   '{"correct": 3}',
   'Rising scores with worse answers are the classic sign of reward hacking. Stop earlier, or improve the reward model, and judge quality with people.'),
  ('llm-whats-coming', 1, 'multiple_choice',
   '{"question": "How can one model handle text, audio and images natively?", "options": ["It can''t, each type needs a different kind of model", "Audio and images are turned into tokens too, and the model trains on mixed sequences", "The model only reads file names", "A separate person describes each image in text"]}',
   '{"correct": 1}',
   'The same idea extends beyond text: chop audio and images into tokens and train on sequences that mix them. The core of the model stays the same.'),
  ('llm-whats-coming', 2, 'multiple_choice',
   '{"question": "In this context, what is an agent?", "options": ["A model that works on a longer task over many steps, using tools, with a person checking in", "A model that only answers yes or no", "A person who sells AI products", "A browser extension that blocks ads"]}',
   '{"correct": 0}',
   'Agents take on tasks rather than single questions. Because they can make mistakes, a person supervises them, like a manager with a team.'),
  ('llm-whats-coming', 3, 'multiple_choice',
   '{"question": "What do computer-using agents do?", "options": ["Use a keyboard and mouse to carry out tasks in apps and websites", "Repair computer hardware", "Only run in data centers with no screens", "Write new operating systems by themselves"]}',
   '{"correct": 0}',
   'These agents look at the screen and take actions, like clicking and typing, so they can work in tools that have no API.'),
  ('llm-whats-coming', 4, 'multiple_choice',
   '{"question": "Which of these was still an open research problem at the time of the video?", "options": ["Training on internet text", "Turning text into tokens", "Running a model on a GPU", "Handling very long contexts well"]}',
   '{"correct": 3}',
   'Tokenization, GPU training and pretraining are well understood. Making models work well over very long contexts, like long tasks and documents, was still being researched.'),
  ('llm-whats-coming', 5, 'multiple_choice',
   '{"question": "You let an agent open pull requests for small bug fixes. What''s the right way to work with it?", "options": ["Never let it touch code", "Only check its pull requests once a year", "Merge everything automatically, since agents don''t make mistakes", "Review its changes like a junior teammate''s before merging"]}',
   '{"correct": 3}',
   'Agents can save a lot of work, but they make mistakes. Keep a person in the loop for anything that reaches production.'),
  ('llm-choosing-models', 1, 'multiple_choice',
   '{"question": "On some leaderboards, people compare answers from two hidden models and pick the better one. What does that ranking tell you?", "options": ["Which model has the most parameters", "Which models people prefer head to head. It''s useful, but test models on your own tasks too", "Which model is the cheapest", "Exactly which model is best for every task"]}',
   '{"correct": 1}',
   'Human-preference rankings are a good signal of general quality, but your use case may differ. Always try the top candidates on your own problems.'),
  ('llm-choosing-models', 2, 'categorize',
   '{"question": "Which way of using a model fits each need?", "buckets": [{"id": "provider-s-app-or-api", "label": "Provider''s app or API"}, {"id": "open-model-on-a-hosting-service", "label": "Open model on a hosting service"}, {"id": "small-model-on-your-own-machine", "label": "Small model on your own machine"}], "items": [{"id": "the-app-must-work-offline-on-a-laptop", "label": "The app must work offline on a laptop"}, {"id": "you-want-to-try-a-base-model-not-an-assi", "label": "You want to try a base model, not an assistant"}, {"id": "you-need-the-newest-proprietary-frontier", "label": "You need the newest proprietary frontier model"}, {"id": "no-data-may-ever-leave-the-device", "label": "No data may ever leave the device"}, {"id": "you-want-an-open-weight-model-without-ma", "label": "You want an open-weight model without managing GPUs"}, {"id": "you-want-top-quality-and-your-data-may-l", "label": "You want top quality, and your data may leave your network"}]}',
   '{"items": {"you-need-the-newest-proprietary-frontier": "provider-s-app-or-api", "you-want-top-quality-and-your-data-may-l": "provider-s-app-or-api", "you-want-an-open-weight-model-without-ma": "open-model-on-a-hosting-service", "you-want-to-try-a-base-model-not-an-assi": "open-model-on-a-hosting-service", "the-app-must-work-offline-on-a-laptop": "small-model-on-your-own-machine", "no-data-may-ever-leave-the-device": "small-model-on-your-own-machine"}}',
   'Proprietary models are used through their makers'' apps and APIs. Open-weight models, including some base models, can be rented from hosting services. Smaller versions can run locally when you need offline use or full data control.'),
  ('llm-choosing-models', 3, 'multiple_choice',
   '{"question": "What does \"open weights\" mean?", "options": ["The training data is public", "The model''s parameters are published, so anyone can download and run it", "The model is free to use on the maker''s website", "The model has no safety training"]}',
   '{"correct": 1}',
   'With open weights you get the parameters themselves. You can run, host or fine-tune the model yourself.'),
  ('llm-choosing-models', 4, 'multiple_choice',
   '{"question": "To run a model on a laptop with a tool like LM Studio, what do you usually use?", "options": ["A model with no tokenizer", "A smaller, distilled model, often quantized to use less memory", "Only base models", "The largest model available"]}',
   '{"correct": 1}',
   'Laptops don''t have the memory for huge models. Distilled models are smaller versions trained from bigger ones, and quantization stores their parameters with fewer bits.'),
  ('llm-choosing-models', 5, 'multiple_choice',
   '{"question": "The field moves fast. What''s a sensible way to keep up?", "options": ["Switch to every new model the day it comes out", "Follow a few trusted sources, like a leaderboard and a newsletter, and try new models on your own tasks", "Read only the providers'' press releases", "Ignore new models for several years"]}',
   '{"correct": 1}',
   'A few good sources keep you informed without the noise, and your own tests show whether a new model actually helps you.'),
  ('llm-choosing-models', 6, 'multiple_choice',
   '{"question": "Your client''s app must work on a factory floor with no internet, on an ordinary laptop. Which option fits?", "options": ["A small open-weight model running locally", "An open model on a hosting service", "A thinking model in the cloud", "The largest proprietary model through its API"]}',
   '{"correct": 0}',
   'No internet rules out every hosted option. A small local model is the one choice that works offline.'),
  ('llm-capstone', 1, 'system_builder',
   '{"question": "Build the path from internet text to a chat answer: add the parts you need and connect them.", "scenario": "Connect the main stages of building and using an LLM, from raw web pages to the answer a user sees in a chat app.", "noun": {"one": "part", "other": "parts"}, "nodes": [{"id": "pretraining", "label": "Pretraining", "role": "Creates the base model"}, {"id": "scanner", "label": "Document scanner", "role": "Reads paper forms"}, {"id": "spreadsheet", "label": "Spreadsheet", "role": "Stores user lists"}, {"id": "fine-tuning", "label": "Fine-tuning on chats", "role": "Creates the assistant"}, {"id": "rl", "label": "Reinforcement learning", "role": "Practices problems"}, {"id": "web-data", "label": "Web data", "role": "Filtered internet text"}, {"id": "chat-app", "label": "Chat app", "role": "Samples an answer"}, {"id": "tokenizer", "label": "Tokenizer", "role": "Turns text into tokens"}]}',
   '{"nodes": ["web-data", "tokenizer", "pretraining", "fine-tuning", "rl", "chat-app"], "connections": [{"from": "web-data", "to": "tokenizer"}, {"from": "tokenizer", "to": "pretraining"}, {"from": "pretraining", "to": "fine-tuning"}, {"from": "fine-tuning", "to": "rl"}, {"from": "rl", "to": "chat-app"}]}',
   'Web text is cleaned and tokenized, pretraining turns it into a base model, fine-tuning on conversations makes it an assistant, and RL sharpens its problem solving. The chat app then samples answers from the finished model.'),
  ('llm-capstone', 2, 'ordering',
   '{"question": "Put the life of one chat message in order.", "items": [{"id": "you-type-a-message", "label": "You type a message"}, {"id": "the-tokens-are-turned-back-into-text-and", "label": "The tokens are turned back into text and shown to you"}, {"id": "the-text-is-split-into-tokens", "label": "The text is split into tokens"}, {"id": "the-app-wraps-it-in-the-chat-template", "label": "The app wraps it in the chat template"}, {"id": "the-model-predicts-and-samples-tokens-on", "label": "The model predicts and samples tokens one at a time"}]}',
   '{"order": ["you-type-a-message", "the-app-wraps-it-in-the-chat-template", "the-text-is-split-into-tokens", "the-model-predicts-and-samples-tokens-on", "the-tokens-are-turned-back-into-text-and"]}',
   'Your message is formatted and tokenized, the model generates the reply token by token, and the tokens are turned back into text.'),
  ('llm-capstone', 3, 'multiple_choice',
   '{"question": "Which training stage gives the model most of its knowledge?", "options": ["RLHF", "Tokenization", "Fine-tuning on conversations", "Pretraining"]}',
   '{"correct": 3}',
   'Pretraining on trillions of tokens builds the model''s knowledge. Later stages mostly shape how it uses that knowledge.'),
  ('llm-capstone', 4, 'multiple_choice',
   '{"question": "When you chat with an assistant, what are you really talking to?", "options": ["A database of approved answers", "A person typing very fast", "A search engine with a chat window", "A statistical imitation of the people who wrote its training answers, sharpened by RL"]}',
   '{"correct": 3}',
   'The assistant imitates the example answers it was fine-tuned on, with knowledge from pretraining. Thinking models add problem-solving skills learned through RL.'),
  ('llm-capstone', 5, 'multiple_choice',
   '{"question": "You''re about to ship a feature that puts an LLM''s answer straight into customer emails. What''s the best practice?", "options": ["Only use the model on weekends", "Treat it as a draft: check facts against sources, use tools for exact details, and keep a review step", "Ask the model if its answer is correct, then send it", "Send it as is, since the model sounds confident"]}',
   '{"correct": 1}',
   'LLMs are powerful tools with jagged abilities. Give them the right context, use tools for exact work, and check their output before it reaches customers.');
